-- 1. Brooklyn (city, NY, pop=2736074)
INSERT OR IGNORE INTO entity
  (id, type, slug, canonical_name, status, language_default, popularity_score, summary, created_at, updated_at)
VALUES
  ('plc_brooklyn', 'place', 'brooklyn', 'Brooklyn', 'published', 'en', 27,
   'Brooklyn, coextensive with Kings County, is the most populous of the five boroughs and counties in New York City, United States. Located at the westernmost end of Long Island and formerly an independent city, Brooklyn shares a land border with the borough and county of Queens. It has several bridge and tunnel connections to the borough of Manhattan, across the East River, including the architecturally significant Brooklyn Bridge, and is connected to Staten Island by the Verrazzano–Narrows Bridge.', unixepoch(), unixepoch());

