-- 2. Queens (city, NY, pop=2316841)
INSERT OR IGNORE INTO entity
  (id, type, slug, canonical_name, status, language_default, popularity_score, summary, created_at, updated_at)
VALUES
  ('plc_queens', 'place', 'queens', 'Queens', 'published', 'en', 23,
   'Queens, coextensive with Queens County, is the largest by area of the five boroughs and counties in New York City, New York, United States. Located near the western end of Long Island, it is bordered by the borough of Brooklyn to its west, and by Nassau County to its east, and shares maritime borders with the boroughs of Manhattan, The Bronx, and Staten Island, as well as with New Jersey. Queens is the most linguistically diverse place in the world, as well as one of the most ethnically diverse.', unixepoch(), unixepoch());

