INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_pueblo_geography', 'plc_pueblo', 'geography', 'Geography',
   'Pueblo tribes [ edit ] Of the federally recognized Native American communities in the Southwest, those designated by the King of Spain as pueblo at the time Spain ceded territory to the United States, after the American Revolutionary War, are legally recognized as Pueblo by the Bureau of Indian Affairs . Some of the pueblos also came under the jurisdiction of the United States, in its view, by its treaty with Mexico , which had briefly gained rule over territory in the Southwest ceded by Spain after Mexican independence. There are 21 federally recognized Pueblos &#91; 1 &#93; that are home to Pueblo peoples . Their official federal names are as follows: Hopi Tribe of Arizona ( Uto-Aztecan ) Ohkay Owingeh , New Mexico (Kiowa-Tanoan) Pueblo of Acoma , New Mexico ( Keresan ) Pueblo of Cochiti , New Mexico (Keresan) Pueblo of Isleta , New Mexico (Kiowa-Tanoan) Pueblo of Jemez , New Mexico ( Kiowa-Tanoan ) Pueblo of Laguna , New Mexico (Keresan) Pueblo of Nambe , New Mexico (Kiowa-Tanoan) Pueblo of Picuris , New Mexico (Kiowa-Tanoan) Pueblo of Pojoaque , New Mexico (Kiowa-Tanoan) Pueblo of San Felipe , New Mexico (Keresan) Pueblo of San Ildefonso , New Mexico (Kiowa-Tanoan) Pueblo of Sandia , New Mexico (Kiowa-Tanoan) Pueblo of Santa Ana , New Mexico (Keresan) Pueblo of Santa Clara , New Mexico (Kiowa-Tanoan) Pueblo of Taos , New Mexico (Kiowa-Tanoan) Pueblo of Tesuque , New Mexico (Kiowa-Tanoan) Pueblo of Zia , New Mexico (Keresan) Santo Domingo Pueblo (also Kewa Pueblo ), New Mexico (Keresan) Ysleta Del Sur Pueblo , Texas (Kiowa-Tanoan) Zuni Tribe of the Zuni Reservation , New Mexico ( Zuni ) &#91; 2 &#93; One unrecognized tribe , the Piro/Manso/Tiwa Indian Tribe of the Pueblo of San Juan Guadalupe is currently &#91; when? &#93; petitioning the US Department of the Interior for federal recognition. &#91; 3 &#93; &#91; needs update &#93; ^ "Indian Entities Recognized and Eligible To Receive Services From the United States Bureau of Indian Affairs; Notice" Federal Regist', '["clm_wiki_pueblo_geography"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'places_ingest_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   30, 1, 1, unixepoch());

INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_pueblo_demographics', 'plc_pueblo', 'demographics', 'Demographics',
   'Civic institutions [ edit ] Indian Pueblo Cultural Center , Albuquerque, New Mexico Each Pueblo is autonomous with its own governmental structure. Several organizations serve to unite the interests of difference Pueblos including the Albuquerque-based All Pueblo Council of Governors &#91; 1 &#93; who collectively negotiates for land and water rights and advocates for Pueblo interests with the state and federal government. The interests of Eight Northern Pueblos are served by the Eight Northern Indian Pueblos Council based in Ohkay Owingeh (formerly San Juan Pueblo). &#91; 1 &#93; Cochiti, Jemez, Sandia, Santa Ana, and Zia are served by the Five Sandoval Indian Pueblos, a nonprofit organization based in Rio Rancho. &#91; 1 &#93; The Indian Pueblo Cultural Center , founded in 1976 in Albuquerque, educates the public about all Pueblos through art, dance, and educational experiences. &#91; 2 &#93; The center has a museum that presents Pueblo history and artifacts, and an interactive Pueblo House museum. An archive holds a collection of photographs, books, and tape recordings of oral histories. &#91; 3 &#93; It also has a café and a restaurant, &#91; 2 &#93; Indian Pueblo Kitchen, serving Indigenous cuisine . &#91; 4 &#93; @media(min-width:640px){.mw-parser-output .infobox{margin-left:1em;float:right;clear:right;width:22em}}.mw-parser-output .infobox-subbox{padding:0;border:none;margin:-3px;width:auto;min-width:100%;font-size:100%;clear:none;float:none;background-color:transparent;color:inherit}.mw-parser-output .infobox-3cols-child{margin:-3px}.mw-parser-output .infobox .navbar{font-size:100%}.mw-parser-output .infobox-hiddenrow,body.skin--responsive.skin--responsive .mw-parser-output .infobox .infobox-hiddenrow{display:none}@media screen{html.skin-theme-clientpref-night .mw-parser-output .infobox-full-data:not(.notheme)>div:not(.notheme)[style]{background:#1f1f23!important;color:#f8f9fa}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-pa', '["clm_wiki_pueblo_demographics"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'places_ingest_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   40, 1, 1, unixepoch());

