INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_reading_demographics', 'plc_reading', 'demographics', 'Demographics',
   'Cognitive benefits [ edit ] Senior reading a newspaper in Nepal Reading for pleasure has been linked to increased cognitive progress in vocabulary and mathematics during adolescence. &#91; 1 &#93; &#91; 2 &#93; &#91; 3 &#93; Sustained high volume lifetime reading has been associated with high levels of academic attainment. &#91; 4 &#93; Research suggests that reading can improve stress management, &#91; 5 &#93; memory, &#91; 5 &#93; focus, &#91; 6 &#93; writing skills, &#91; 6 &#93; and imagination . &#91; 7 &#93; The cognitive benefits of reading continue into mid-life and the senior years. &#91; 8 &#93; &#91; 9 &#93; &#91; 10 &#93; Research suggests that reading books and writing are among the brain-stimulating activities that can slow down cognitive decline in seniors. &#91; 11 &#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:"\"""\"""''""''"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url("//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url("//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url("//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url("//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-mine', '["clm_wiki_reading_demographics"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'places_ingest_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
