VALUES
  ('cs_saint-joseph_overview', 'plc_saint-joseph', 'overview', 'Overview',
   'According to the canonical Gospels, Joseph was a 1st-century Jewish man of Nazareth who was married to Mary, the mother of Jesus, and was the legal father of Jesus.', '["clm_wiki_saint-joseph_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'places_ingest_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
