-- 360. Prattville (city, AL, pop=35420)
INSERT OR IGNORE INTO entity
  (id, type, slug, canonical_name, status, language_default, popularity_score, summary, created_at, updated_at)
VALUES
  ('plc_prattville', 'place', 'prattville', 'Prattville', 'published', 'en', 0,
   'Prattville is a city located within both Autauga and Elmore counties in the State of Alabama, United States, and serves as the county seat of Autauga County. As of the 2020 census, the population of the city was 37,781. Nicknamed "The Fountain City" due to the many artesian wells in the area, Prattville is part of the Montgomery Metropolitan Area. It was founded by Daniel Pratt.', unixepoch(), unixepoch());

