-- 484. Woodstock (city, IL, pop=25189)
INSERT OR IGNORE INTO entity
  (id, type, slug, canonical_name, status, language_default, popularity_score, summary, created_at, updated_at)
VALUES
  ('plc_woodstock', 'place', 'woodstock', 'Woodstock', 'published', 'en', 0,
   'The Woodstock Music and Art Fair, commonly referred to as Woodstock, was a music festival held from August 15 to 18, 1969, on Max Yasgur''s dairy farm in Bethel, New York, 60 miles (95 km) southwest of the town of Woodstock. Billed as "an Aquarian Exposition: 3 Days of Peace & Music", it attracted an audience of more than 460,000. Thirty-two acts performed outdoors despite overcast skies and sporadic rain. It was one of the largest music festivals in history and would become the peak musical event to reflect the counterculture of the 1960s.', unixepoch(), unixepoch());

