INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_tiffin_history', 'plc_tiffin', 'history', 'History',
   'Etymology [ edit ] In the British Raj , tiffin was used to denote the British custom of afternoon tea that had been supplanted by the Indian practice of having a light meal at that hour. &#91; 1 &#93; It is derived from "tiffing", an English colloquial term meaning to take a little drink. By 1867 it had become naturalised among Anglo-Indians in northern British India to mean luncheon. &#91; 2 &#93; ^ Quinion 2006 , Tiffin. ^ OED staff 2013 , "tiffin, n."cites H. Wedgwood (1862) " Tiffin , now naturalised among Anglo-Indians in the sense of luncheon, is the North country tiffing (properly sipping)". See also Wedgwood 1872 , p.&#160;682.', '["clm_wiki_tiffin_history"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'places_ingest_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   20, 1, 1, unixepoch());

INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_tiffin_geography', 'plc_tiffin', 'geography', 'Geography',
   'Current usage [ edit ] Two dabbawalas in Mumbai delivering meals packed in tiffin carriers In South India and in Nepal, tiffin is generally breakfast or a snack between meals: dosas , idlis , vadas etc. &#91; 1 &#93; In other parts of India, such as Mumbai , the word mostly refers to a packed lunch of some sort. &#91; 2 &#93; In Mumbai, it is often delivered to them by dabbawalas , sometimes known as tiffin wallahs , who use a complex system to get thousands of tiffin carriers to their destinations. In most of India, a school-going child''s lunch box is fondly called a tiffin box. &#91; 3 &#93; It is also used heavily in Pakistan where people use tiffin boxes in places like offices, schools or during picnic. This practice is also common in India. When used in place of the word "lunch", tiffin often consists of rice, lentils , curry , vegetables, chapatis or "spicy meats". &#91; 4 &#93; In addition, the lunch boxes are themselves called tiffin carriers , tiffin-boxes or just tiffins. ^ Hughes, Mookherjee &amp; Delacy 2001 , p.&#160;25. ^ Harding 2002 . ^ Thakker 2005 . ^ Murray 2008 , pp.&#160;85–108.', '["clm_wiki_tiffin_geography"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'places_ingest_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   30, 1, 1, unixepoch());

