-- 643. Culpeper (city, VA, pop=17557)
INSERT OR IGNORE INTO entity
  (id, type, slug, canonical_name, status, language_default, popularity_score, summary, created_at, updated_at)
VALUES
  ('plc_culpeper', 'place', 'culpeper', 'Culpeper', 'published', 'en', 0,
   'Culpeper is an incorporated town in Culpeper County, Virginia, United States. It is the county seat and part of the Washington–Baltimore combined statistical area. At the 2020 United States Census, the population was 20,062, an increase from 16,379 in 2010. Culpeper is located along U.S. Route 15, U.S. Route 29, and U.S. Route 522, and is served by intercity passenger rail at Culpeper station and by local and regional bus services operated by Virginia Regional Transit and the Virginia Breeze network.', unixepoch(), unixepoch());

