-- 651. Bristol (city, VA, pop=17141)
INSERT OR IGNORE INTO entity
  (id, type, slug, canonical_name, status, language_default, popularity_score, summary, created_at, updated_at)
VALUES
  ('plc_bristol', 'place', 'bristol', 'Bristol', 'published', 'en', 0,
   'Bristol is a city and ceremonial county in South West England. It is on the River Avon, and bordered by Gloucestershire to the north and Somerset to the south, with a short coastline on the Bristol Channel to the west. The county includes most of the Bristol conurbation, but the urban area extends into South Gloucestershire, Bath and North East Somerset, and North Somerset.', unixepoch(), unixepoch());

