-- 675. Vero Beach (city, FL, pop=16358)
INSERT OR IGNORE INTO entity
  (id, type, slug, canonical_name, status, language_default, popularity_score, summary, created_at, updated_at)
VALUES
  ('plc_vero-beach', 'place', 'vero-beach', 'Vero Beach', 'published', 'en', 0,
   'Vero Beach is a city in and the county seat of Indian River County, Florida, United States. According to the 2020 census, the city had a population of 16,354. Nicknamed "The Hibiscus City", Vero is situated about 85 miles (137 km) southeast of Orlando along the Indian River Lagoon and the Atlantic Ocean on Florida''s Treasure Coast. Because it is located about 65 miles (105 km) north of West Palm Beach at the northern end of the South Florida region, the city has adopted two similar mottos "The Gateway to the Tropics" and "Where the Tropics Begin".', unixepoch(), unixepoch());

