-- 727. Hereford (city, TX, pop=15021)
INSERT OR IGNORE INTO entity
  (id, type, slug, canonical_name, status, language_default, popularity_score, summary, created_at, updated_at)
VALUES
  ('plc_hereford', 'place', 'hereford', 'Hereford', 'published', 'en', 0,
   'Hereford is a cathedral city and the county town of the ceremonial county of Herefordshire, England. It is on the banks of the River Wye and lies 16 miles (26 km) east of the border with Wales, 23 miles (37 km) north-west of Gloucester and 24 miles (39 km) south-west of Worcester. With a population of 61,900 in 2024, it is the largest settlement in Herefordshire.', unixepoch(), unixepoch());

