-- 815. Minden (city, LA, pop=12690)
INSERT OR IGNORE INTO entity
  (id, type, slug, canonical_name, status, language_default, popularity_score, summary, created_at, updated_at)
VALUES
  ('plc_minden', 'place', 'minden', 'Minden', 'published', 'en', 0,
   'Minden is a middle-sized town in the very north-east of North Rhine-Westphalia, Germany, the largest town in population between Bielefeld and Hanover. It is the capital of the district of Minden-Lübbecke, situated in the cultural region of Ostwestfalen-Lippe (OWL) and the administrative region of Detmold. The town extends along both sides of the River Weser, and is crossed by the Mittelland Canal, which is led over the river on the Minden Aqueduct.', unixepoch(), unixepoch());

