INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_somerset_history', 'plc_somerset', 'history', 'History',
   'Toponymy [ edit ] Somerset''s name most likely derives from Old English Sumorsǣte , short for Sumortūnsǣte , meaning "the people living at or dependent on Sumortūn " (now known as Somerton ). &#91; 1 &#93; An alternative suggestion is that the name derives from Seo-mere-saetan meaning "settlers by the sea lakes". &#91; 2 &#93; The same ending can also be seen in the neighbouring Dorset . The first known use of Somersæte is in the law code of King Ine who was the Saxon King of Wessex from 688 to 726&#160;CE, making Somerset along with Hampshire , Wiltshire and Dorset one of the oldest extant units of local government in the world. &#91; 3 &#93; The Old English name is used in the motto of the county, Sumorsǣte ealle , meaning "all the people of Somerset". Adopted as the motto in 1911, the phrase is taken from the Anglo-Saxon Chronicle . Somerset was a shire of the Anglo-Saxon kingdom of Wessex , and the phrase refers to the wholehearted support the people of Somerset gave to King Alfred in his struggle to save Wessex from Viking invaders. &#91; 4 &#93; &#91; 5 &#93; &#91; 6 &#93; Somerset settlement names are mostly Anglo-Saxon in origin (for example, Bath , Somerton , Wells and Keynsham &#91; 7 &#93; ), but numerous place names include British Celtic elements, such as the rivers Frome and Avon, and names of hills. For example, an Anglo-Saxon charter of 682 refers to Creechborough Hill as "the hill which in the British language is Cructan and which to us is Crychbeorh ". &#91; 8 &#93; Some modern names are wholly Brittonic in origin, like Tarnock , Priddy and Chard , while others have both Saxon and Brittonic elements, such as Pen Hill . &#91; 9 &#93; &#91; 10 &#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:"\"""\"""''""''"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url("//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url("//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url("//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{backgr', '["clm_wiki_somerset_history"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'places_ingest_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   20, 1, 1, unixepoch());

INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_somerset_geography', 'plc_somerset', 'geography', 'Geography',
   'History [ edit ] .mw-parser-output .hatnote{font-style:italic}.mw-parser-output div.hatnote{padding-left:1.6em;margin-bottom:0.5em}.mw-parser-output .hatnote i{font-style:normal}.mw-parser-output .hatnote+span.mw-empty-elt+.hatnote,.mw-parser-output .hatnote+link+.hatnote{margin-top:-0.5em}@media print{body.ns-0 .mw-parser-output .hatnote{display:none!important}} Main article: History of Somerset A map of the county in 1646, author unknown Prehistory [ edit ] The caves of the Mendip Hills were settled during the Palaeolithic period, &#91; 1 &#93; and contain extensive archaeological sites such as those at Cheddar Gorge . Bones from Gough''s Cave have been dated to 12,000&#160;BCE, and a complete skeleton, known as Cheddar Man , dates from 7150&#160;BCE . &#91; 2 &#93; Examples of cave art have been found in Aveline''s Hole . &#91; 3 &#93; Some caves continued to be occupied until modern times, including Wookey Hole . The Somerset Levels —specifically dry points at Glastonbury and Brent Knoll —also have a long history of settlement, and are known to have been settled by Mesolithic hunters. &#91; 4 &#93; &#91; 5 &#93; Travel in the area was facilitated by the construction of one of the world''s oldest known engineered roadways, the Sweet Track , which dates from 3807&#160;BCE or 3806&#160;BCE. &#91; a &#93; &#91; 7 &#93; &#91; 8 &#93; The exact age of the henge monument at Stanton Drew stone circles is unknown, but it is believed to be Neolithic . &#91; 9 &#93; There are numerous Iron Age hill forts , some of which, like Cadbury Castle &#91; 10 &#93; and Ham Hill , were later reoccupied in the Early Middle Ages . &#91; 11 &#93; Roman invasion [ edit ] On the authority of the future emperor Vespasian , as part of the ongoing expansion of the Roman presence in Britain, the Second Legion Augusta invaded Somerset from the south-east in 47&#160;CE. The county remained part of the Roman Empire until around 409&#160;CE, when the Roman occupation of Britain came to an end. &#91;', '["clm_wiki_somerset_geography"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'places_ingest_v1', 'auto_approved', 1, unixepoch(), unixepoch(),
   30, 1, 1, unixepoch());

