-- 881. Saint Peter (city, MN, pop=11196)
INSERT OR IGNORE INTO entity
  (id, type, slug, canonical_name, status, language_default, popularity_score, summary, created_at, updated_at)
VALUES
  ('plc_saint-peter', 'place', 'saint-peter', 'Saint Peter', 'published', 'en', 0,
   'Saint Peter, also known as Peter the Apostle and Simon Peter, or Cephas was one of the Twelve Apostles of Jesus and one of the first leaders of the early Christian Church. He appears repeatedly and prominently in all four New Testament gospels, as well as the Acts of the Apostles. Catholic and Orthodox tradition treats Peter as the first bishop of Rome – or pope – and also as the first bishop of Antioch. According to Christian tradition, Peter was crucified in Rome under Emperor Nero.', unixepoch(), unixepoch());

